const read = this.progress
if (this.heldProgress?.read !== read) this.heldProgress = { read, clients: read.map(progress => new FidelityProgressClient(progress, this)) }
return this.heldProgress.clients

if (!this.next || this.isLocked) return false
// Opening the report while violations hold the fidelity is done on the board, so it needs no chat.
return this.nextProgress?.state === 'violations' || this.page.chat.canSend

if destination in self.files or self._checked is None:
    return
destination.write_text(self._checked.text, encoding="utf-8")

judged = [
    (fidelity, format)
    for fidelity, format in zip(self._fidelities, self._formats)
    if (bool(self.files) and fidelity.is_judged_on_graph) == on_graph
]
return "; ".join(f"{format}: {', '.join(self.edited or fidelity.output_paths().get(format, []))}" for fidelity, format in judged)

if self.prefixes and self._named in (None, True) and self._fidelities:
    return [self._built_at(reports.graph_file())]
if self._named is True:
    return self._session_saved()
return self._read_named()

others = [
    self.session.path_named(path)
    for fidelity, checked in zip(self._fidelities, self._formats)
    for format, paths in fidelity.output_paths().items()
    if format != checked
    for path in paths
    if "{" not in path
]
return {path.relative_to(self.session.work_root).as_posix() for path in others if self.session.session_files.in_root(path)}

declared = [path for fidelity, checked in zip(self._fidelities, self._formats) for path in fidelity.output_paths().get(checked, [])]
found = [self.session.path_named(path) for path in declared if "{" not in path]
folders = {path.parent if path.is_file() else path for path in found if path.exists()}
return sorted(str(folder) for folder in folders if self.session.session_files.in_root(folder))

self._work_on(guidance)
sections: list[str] = [_VALIDATE_MARKDOWN]
fidelities = self._fidelities()
self._graph = CheckedGraph(self.session, fidelities, NamedToCheck(paths, graph, self.call))
self._reports = ReportFiles(self.session, fidelities)
graph_paths = self._graph.check_beside(self._reports)
if fidelities:
    sections.append(self._judging_instruction())
if graph_paths:
    sections.append(self._graph_and_ai_rule_report())
elif graph:
    sections.append(
        "No saved graph found. Run graph.load_working_copy on the session's folder, which saves "
        ".context/graph.json there, or pass graph as a path to graph_return_nodes JSON."
    )

def on(item) -> str:
    if rule is not None:
        return rule.validate()
    if isinstance(item, str):
        return item
    if graph_paths:
        return ""
    return item.checked_rules_text()

parts = [part for part in self.run(on, action="validate") if part]
sections.extend(parts)
overlay_rules = self._overlay_rules()
if overlay_rules:
    sections.append(f"Judge the work against these overlaid patterns' rules too, as you judge the practices' rules.\n\n{overlay_rules}")
report = "\n\n".join(sections)
self._reports.save(report, self._graph)
return f"{report}\n\nValidation report for these artifacts: {self._reports.where()}"

graph_judged = self._graph.judged_files(on_graph=True)
file_judged = self._graph.judged_files(on_graph=False)
sentences = []
if graph_judged:
    sentences.append(
        f"Judge the graph validate built from the checked format's files ({graph_judged}), "
        f"saved at {', '.join(str(path) for path in self._graph.files)}: its classes, operations, parameters, "
        "properties, relationships, and dependencies, against each rule. Read a file only to see what a node "
        "stands for; whether a model document matches the code is a separate, secondary check."
    )
if file_judged:
    sentences.append(
        f"Judge only the checked format's files ({file_judged}). The other formats mirror "
        "them, so judging those too reports every finding twice."
    )
return "\n\n".join(sentences)

if self.work.text is not None or not violations:
    return
synopsis = [
    f"graph-rule {violation.rule} {violation.location}:{violation.line or ''}"
    for violation in violations[:_LOGGED_VIOLATIONS]
]
if len(violations) > _LOGGED_VIOLATIONS:
    synopsis.append(f"graph-rule … and {len(violations) - _LOGGED_VIOLATIONS} more")
for worked in self._worked_fidelities():
    self.log.validation(worked, synopsis)
# This line is the call's validate line; the session board reads the latest one, so no clean line may follow.
self._logged_session_action = "validate"

if self.work.text is not None:
    return
for worked in self._worked_fidelities():
    self.log.validation(worked, [])

self._work_on(guidance)

def on(item) -> str:
    if isinstance(item, str):
        return ""
    return "\n\n".join(part.strip() for part in (str(item.examples or ""), item.templates or "") if part.strip())

self.run(on, action="create_rule")
return (
    "Write a new named rule into this tool. "
    "Then run collection validate on the asset and detect a failure "
    "that matches the Mistake."
)

const saved = await super.setSendsFixesDirectly(sends)
await this.page.reader.refresh()
return saved

const names = new Set(this.tickets.map(ticket => ticket.name))
const earlierHeld = before.backlogItems.map(item => item.ticket)
const held = this.backlogItems.map(item => item.ticket)
return before.tickets
  .filter(ticket => !names.has(ticket.name) && held.includes(ticket.name) && !earlierHeld.includes(ticket.name))
  .map(ticket => `${ticket.title} moved to Backlog`)

const earlier = new Map(before.tickets.map(ticket => [ticket.name, ticket]))
const named = this.tickets.map(ticket => ticket.name)
const isUnique = (ticket: TicketClient) => named.indexOf(ticket.name) === named.lastIndexOf(ticket.name)
const changes = this.tickets.flatMap(ticket => {
  const was = earlier.get(ticket.name)
  return was && isUnique(ticket) ? changesOf(was, ticket) : []
})
return [...changes, ...this.returnsSince(before)]

const { page } = useBoard()
const onDragStart = (event: DragEvent) => {
  event.dataTransfer.setData('text/plain', ticket.name)
  event.dataTransfer.effectAllowed = 'move'
  page.store.change({ dragged: ticket.address })
}
const onDragEnd = () => page.store.change(current => ({ dragged: null, openCard: current.openCard === ticket.name ? null : current.openCard }))
return { onDragStart, onDragEnd }

const { page } = useBoard()
const [isTakingChild, setTakingChild] = useState(false)
// Read when each event arrives, not from the last drawing: a quick drag reaches the card before the page redraws.
const draggedChild = () => {
  const dragged = page.board.tickets.find(entry => entry.address === page.store.state.dragged)
  return dragged && ticket.canTakeAsChild(dragged) ? dragged : undefined
}
const onDragOver = (event: DragEvent) => {
  if (!draggedChild()) return
  event.preventDefault()
  event.stopPropagation()
  setTakingChild(true)
}
// The card takes the drop, so the list under it does not move the ticket to its column as well.
const onDrop = (event: DragEvent) => {
  setTakingChild(false)
  const dragged = draggedChild()
  if (!dragged) return
  event.preventDefault()
  event.stopPropagation()
  page.store.change({ dragged: null })
  void ticket.takeAsChild(dragged)
}
return { isTakingChild, onDragOver, onDragLeave: () => setTakingChild(false), onDrop }

const source = useDragSource(ticket)
const { isTakingChild, ...target } = useChildDrop(ticket)
return { isTakingChild, handlers: { ...source, ...target } }

const { progress } = panel
return (
  <>
    <p className="panel-warning">This report's saved graph is out of date, so its graph's rules are not shown. Validate again to read them.</p>
    {progress ? (
      <button className="ghost-button" disabled={isOff} title={isOff ? 'Connect a chat to validate' : 'Ask the chat to validate this fidelity again'} onClick={() => void panel.ticket.validateAgain(progress)}>
        Validate again
      </button>
    ) : null}
  </>
)

const { report } = panel
if (!report.path) return <p className="panel-note">No validation report yet.</p>
if (report.isOutOfDate) return <OutOfDateView panel={panel} isOff={isOff} />
// The raw text stands in for the rules only when none could be read from it; otherwise it pushes them out of view.
if (!report.hasSavedGraph) {
  return (
    <>
      <p className="panel-warning">This report has no saved graph, so its rules are only in the report file.</p>
      {report.rules.length ? null : <pre className="report-text">{report.text}</pre>}
    </>
  )
}
return report.rules.length ? null : <p className="panel-clean">No open violations. The fidelity is done.</p>

const { page, state } = useBoard()
const isOff = panel.ticket.isLocked || !page.chat.canSend
return (
  <div className="panel-body report-body" key={state.board?.project}>
    <ReportStandingView panel={panel} isOff={isOff} />
    {panel.report.rules.length ? (
      <button className="ghost-button" disabled={isOff} title={isOff ? 'Connect a chat to send fixes' : panel.report.fixes.title} onClick={() => void panel.report.fixes.fixReport()}>
        Fix all violations
      </button>
    ) : null}
    {panel.report.rules.map(rule => (
      <RuleView key={`${rule.fidelity.slug}/${rule.rule.slug}`} panel={panel} rule={rule} isOff={isOff} />
    ))}
  </div>
)

return (
  <div className={entry.number === violation.line ? 'code-line is-failing' : 'code-line'}>
    <span className="line-number">{entry.number}</span>
    <span className="line-text">{entry.text}</span>
  </div>
)

const { page } = useBoard()
const location = locationOf(violation)
const line = violation.line ?? 1
// A location with no source has no file to open, so only one with source lines is a link.
if (!violation.source.length) return <span className="file-location">{location}</span>
return (
  <button className="file-link" title={`Open at line ${line}`} onClick={() => void page.files.openFileAtLine(panel.ticket, panel.ticket.progressNamed(rule.fidelity.slug), violation.location, line)}>
    {location}
  </button>
)

return (
  <div className="violation-source">
    <div className="source-fence">
      <ViolationLocationView panel={panel} rule={rule} violation={violation} />
    </div>
    {violation.source.map(entry => (
      <SourceLineView key={entry.number} violation={violation} entry={entry} />
    ))}
  </div>
)

const { page } = useBoard()
const hasSource = violation.source.length > 0
return (
  <article className="violation">
    <div className="violation-head">
      <div className="violation-words">
        {hasSource ? null : <ViolationLocationView panel={panel} rule={rule} violation={violation} />}
        <div className="violation-message">{violation.message}</div>
      </div>
      <button className="fix-button" aria-label={`Fix ${locationOf(violation)}`} disabled={isOff} title={isOff ? 'Connect a chat to send fixes' : panel.report.fixes.title} onClick={() => void panel.report.fixes.fixViolation(rule, violation)}>
        Fix
      </button>
    </div>
    {hasSource ? <ViolationSourceView panel={panel} rule={rule} violation={violation} /> : null}
  </article>
)

const place = `${rule.fidelity.slug}/${rule.rule.slug}`
const isOpen = !panel.closedRules.includes(place)
return (
  <section className="report-rule">
    <RuleHeadView report={panel.report} rule={rule} place={place} isOpen={isOpen} isOff={isOff} />
    {isOpen ? rule.violations.map((violation, index) => <ViolationView key={`${violation.location}-${violation.line}-${index}`} panel={panel} rule={rule} violation={violation} isOff={isOff} />) : null}
  </section>
)

const border = ticket.isActive ? ACTIVE_BORDER_WIDTH : 1
const span = spot === 'only' ? `100% + ${2 * (9 + border)}px` : `200% + ${4 * border + 26}px`
return { width: `calc(${span})`, top: -border, left: opensLeft ? 'auto' : -border, right: opensLeft ? -border : 'auto', opensLeft }

const { page, state } = useBoard()
const isOpen = state.openCard === ticket.name
return (
  <button className="expand-mark card-mark" aria-label={`Actions for ${ticket.title}`} aria-expanded={isOpen} onClick={withoutSelecting(() => page.cards.toggle(ticket))}>
    {isOpen ? '▴' : '▾'}
  </button>
)

const { page, state } = useBoard()
const [skill, setSkill] = useState('')
return (
  <>
    <CardMarkView ticket={ticket} />
    <div className="ticket-title-line">
      <div className="ticket-title">{ticket.title}</div>
      {ticket.chat.isOpening ? <span className="progress-wheel" role="status" title="Opening its chat in the Claude app" aria-label="Opening its chat" /> : null}
      {ticket.canOpenChat && !ticket.chat.isOpening ? (
        <SessionActionView action="chat" label={`Open the chat of ${ticket.title}`} hint="Open its chat: its worktree and a new chat in the Claude app" isOff={false} onPress={() => ticket.openChat()} />
      ) : null}
      <SplitActionView ticket={ticket} />
      <AddChildView ticket={ticket} />
    </div>
    <div className="ticket-meta">{ageOf(state.now, ticket.lastActivity)}</div>
    <SegmentsView ticket={ticket} stage={stage} onSkill={setSkill} />
    {skill ? <div className="card-skill">{skill}</div> : null}
    {ticket.workIn(stage)?.hasViolations ? (
